export const knownSites = new Map(
    Object.entries(knownSitesList).map(([domain, code]) => [code, domain])
);

export const getDomainCode = (url) => {
    try {
        const domain = new URL(url).hostname.replace(/^www\./, '');
        const parts = domain.split('.');
        return parts[0] || code();
    } catch {
        return code();
    }
}

export const detectSiteCode = (url) => {
    try {
        const parsed = new URL(url);
        const host = parsed.hostname.replace(/^www\./, '');

        for (const domain in knownSitesList) {
            if (host.includes(domain)) {
                return knownSitesList[domain];
            }
        }

        return getDomainCode(url);
    } catch {
        return code();
    }
}

export const isInvalidEmail = (email) => {
    if (!email) {
        return false;
    }

    return !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
}

export const shuffleArray = (array) => {
    const arr = array.slice();
    for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
}

export const shuffleCurrentArray = (items) => {
    for (let i = items.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [items[i], items[j]] = [items[j], items[i]];
    }

    return items;
}

export const createEmitter = () => {
    const events = new Map();
    const watchers = new Set();

    return {
        on(event, handler) {
            if (!events.has(event)) {
                events.set(event, new Set());
            }

            events.get(event).add(handler);
            return () => this.off(event, handler);
        },
        off(event, handler) {
            if (!events.has(event)) {
                return;
            }

            events.get(event).delete(handler);
        },
        watch(handler) {
            watchers.add(handler);

            return () => this.unwatch(handler);
        },
        unwatch(handler) {
            watchers.delete(handler);
        },
        emit(event, ...args) {
            for (const watcher of Array.from(watchers)) {
                try {
                    watcher(event, ...args);
                } catch (e) {
                    console.error('Emitter watcher error', e);
                }
            }

            if (!events.has(event)) {
                return;
            }

            for (const h of Array.from(events.get(event))) {
                try {
                    h(...args);
                } catch (e) {
                    console.error('Emitter handler error', e);
                }
            }
        }
    };
};


export const formatDuration = (ms) => {
    if (!ms || ms < 0) {
        return "00:00";
    }

    const totalSeconds = Math.floor(ms / 1000);
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;

    const pad = (n) => String(n).padStart(2, "0");

    if (hours > 0) {
        return `${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;
    }

    return `${pad(minutes)}:${pad(seconds)}`;
}


