<template>
    <div id="auth-modal-backdrop" class="modal-backdrop" @click="handleBackdropClick">
        <div id="auth-modal-card" class="modal-card" :class="{ open: data.ready }">
            <button id="close-auth-modal-btn" class="close-btn" aria-label="Close modal" @click="close">
                <svg fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12" />
                </svg>
            </button>
            <div class="content">
                <div class="header">
                    <h3 class="title">{{ t('pages.main.modal.title') }}</h3>
                    <p class="subtitle">{{ t('pages.main.modal.subtitle') }}</p>
                </div>
                <div class="modal-instructions">
                    <p class="intro">{{ t('pages.main.modal.instructionIntro') }}</p>
                    <ol class="list">
                        <li v-for="(step, idx) in tm('pages.main.modal.steps')" :key="idx">
                            <span>
                                {{ step }}

                                <Icon v-if="data.icons[idx]"
                                    :icon="data.icons[idx].icon"
                                    :sprite="data.icons[idx].sprite"
                                />
                            </span>
                        </li>
                    </ol>
                </div>
                <div class="hero-pairing-code">
                    <span class="label">{{ t('pages.main.modal.pairingCodeLabel') }}</span>
                    <div class="value">{{ user.externalCode }}</div>
                    <div class="track" v-if="user.externalCode">
                        <div class="bar" :style="{ width: `${data.codeProgressPct}%` }"></div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script setup>
import { onMounted, onBeforeUnmount, reactive, computed } from 'vue';
import { useI18n } from 'vue-i18n';
// import draggable from 'vuedraggable'

// import BaseModal from '🔗/components/modals/BaseModal.vue';
// import Button from '🔗/components/ui/Button.vue';
import Icon from '🔗/components/ui/Icon.vue';
// import ReleasePreview from '🔗/components/ui/ReleasePreview.vue';
// import EmptyLabel from '🔗/components/ui/EmptyLabel.vue';
// import TrackPreview from '🔗/components/ui/TrackPreview.vue';
// import { delay } from '🔗/utils/utils';

// import api from '🔗/api';
// import stores from '@/stores';
const user = stores.user();
const modals = stores.modals();
const appPlugin = stores.appPlugin();

const { t, tm } = useI18n();

const props = defineProps({
    name: {
        type: String,
        default: 'auth'
    }
});

const data = reactive({
    codeProgressPct: 100,
    countdownSeconds: 5 * 60,
    ready: false,
    icons: {
        2: {
            icon: 'favorite',
            sprite: 'actions'
        },
        3: {
            icon: 'settings',
            sprite: 'sections'
        }
    }
});


const stopCountdown = () => {
    if (data.countdownInterval) {
        clearInterval(data.countdownInterval);
        data.countdownInterval = null;
    }
}

const startCountdown = () => {

    data.countdownSeconds = 5 * 60;

    stopCountdown();
    data.countdownInterval = setInterval(() => {
        data.countdownSeconds--;

        if (data.countdownSeconds.value <= 0) {
            updateCode();
        } else {
            data.codeProgressPct = Math.max(0, (data.countdownSeconds / (5 * 60)) * 100);
        }
    }, 1000);
}

const checkCode = async () => {
    const result = await user.checkExternalLogin();

    if (!result) {
        clearTimeout(data.checkCodeTimeout);
        data.checkCodeTimeout = setTimeout(() => {
            checkCode();
        }, 4 * 1000); // Каждые 4 секунды надо запрашивать статус
        return;
    }

    stopCountdown();

    await user.getArtists();

    appPlugin.syncProfiles();

    close();
}

const updateCode = async () => {
    await user.createExternalLogin();

    startCountdown();

    setTimeout(() => {
        checkCode();
    }, 5 * 1000);
}

const close = () => {
    modals.close(props.name);
}

const handleBackdropClick = (e) => {
    if (e.target.classList.contains('modal-backdrop')) {
        close();
    }
}

onBeforeUnmount(() => {
    stopCountdown();
    clearTimeout(data.checkCodeTimeout);
})

onMounted(() => {
    updateCode();
    // data.id = modals.getData(props.name);
    data.ready = true;
});
</script>

<style lang="scss" scoped>
