    @include bapps.transition-smooth(transform opacity, 0.25s);
    transform: scale(0.95);
    opacity: 0;
    display: flex;
    flex-direction: column;
    gap: 1.5rem;

    @include bapps.respond-to("sm") {
        padding: 2.5rem;
    }

    &.open {
        transform: scale(1);
        opacity: 1;
    }

    .close-btn {
        @include bapps.button-reset;
        position: absolute;
        top: 1.75rem;
        right: 1.75rem;
        padding: 0.625rem;
        border-radius: 9999px;
        color: $color-subtle;
        @include bapps.transition-smooth;

        svg {
            width: 1.25rem;
            height: 1.25rem;
        }

        &:hover {
            color: $color-charcoal;
            background-color: rgba(0, 0, 0, 0.04);
        }
    }

    .header {
        padding-right: 2rem;
    }

    .title {
        font-family: $font-display;
        font-weight: 900;
        font-size: 1.5rem;
        color: $color-charcoal;
        letter-spacing: -0.02em;
    }

    .subtitle {
        font-size: 0.8125rem;
        color: $color-subtle;
        margin-top: 0.25rem;

        @include bapps.respond-to("sm") {
            font-size: 0.875rem;
        }
    }

    .content {
        display: flex;
        flex-direction: column;
        gap: 1.5rem;
    }
}

.modal-instructions {
    background-color: rgba(248, 249, 250, 0.7);
    border-radius: 1.5rem;
    padding: 1.5rem;
    border: 1px solid $color-border-subtle;
    display: flex;
    flex-direction: column;
    gap: 0.875rem;

    @include bapps.respond-to("sm") {
        padding: 1.75rem;
    }

    .intro {
        font-size: 0.8125rem;
        font-weight: 700;
        color: $color-charcoal;

        @include bapps.respond-to("sm") {
            font-size: 0.875rem;
        }
    }

    .list {
        font-size: 0.8125rem;
        color: $color-text-medium;
        line-height: 1.6;
        padding-left: 1.25rem;
        margin: 0;
        display: flex;
        flex-direction: column;
        gap: 0.5rem;

        @include bapps.respond-to("sm") {
            font-size: 0.875rem;
        }

        li {
            span {
                display: flex;
                flex-direction: row;
                align-items: center;
                gap: 4px;
                svg {
                    width: 16px;
                    height: 16px;
                }
            }
        }

        li::marker {
            font-weight: 700;
            color: $color-charcoal;
        }
    }
}

.hero-pairing-code {
    background-color: $color-canvas;
    border-radius: 1.5rem;
    padding: 1.5rem 1rem;
    border: 1px solid $color-border-subtle;
    text-align: center;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    min-height: 179px;

    @include bapps.respond-to("sm") {
        padding: 1.75rem 1rem;
    }

    .label {
        font-size: 0.625rem;
        font-family: $font-mono;
        font-weight: 700;
        text-transform: uppercase;
