        color: $color-charcoal;
        user-select: all;
        padding: 0.25rem 0;

        @include bapps.respond-to("sm") {
            font-size: 3rem;
            letter-spacing: 0.2em;
        }
    }

    .track {
        width: 9rem;
        margin: 0 auto;
        height: 2px;
        background-color: rgba(0, 0, 0, 0.06);
        border-radius: 9999px;
        overflow: hidden;

        @include bapps.respond-to("sm") {
            width: 12rem;
        }
    }

    .bar {
        height: 100%;
        background-color: rgba(12, 13, 14, 0.4);
        border-radius: 9999px;
        transition: width 1s linear;
        width: 100%;
    }
}

.modal-action-btn {
    @include bapps.button-reset;
    width: 100%;
    padding: 0.875rem;
    border-radius: 9999px;
    background-color: $color-charcoal;
    color: #ffffff;
    font-weight: 700;
    font-size: 0.8125rem;
    box-shadow: $shadow-xs;
    @include bapps.transition-smooth;

    @include bapps.respond-to("sm") {
        padding: 1rem;
        font-size: 0.875rem;
    }

    &:hover {
        background-color: $color-charcoal-hover;
    }

    &:active {
        transform: scale(0.98);
    }
}
</style>
